            float3 baseOffset,
            Span<CollideShapeResult> results,
            out uint totalHits,
            BroadPhaseLayerFilter broadPhaseLayerFilter,
            ObjectLayerFilter objectLayerFilter,
            BodyFilter bodyFilter,
            ShapeFilter shapeFilter
        )
        {
            fixed (CollideShapeResult* results_fixed = results)
            {
                totalHits = Jolt.PInvoke.CharacterVirtual_CheckCollision(
                    this,
                    position,
                    rotation,
                    movementDirection,
                    maxSeparationDistance,
                    shape,
                    baseOffset,
                    results_fixed,
                    (uint)results.Length,
                    broadPhaseLayerFilter,
                    objectLayerFilter,
                    bodyFilter,
                    shapeFilter
                );
                return totalHits < (uint)results.Length ? totalHits : (uint)results.Length;
            }
        }

